use xiom.io;
enum Choice { Rock; Paper; Scissors; }
enum Outcome { Win; Lose; Draw; }

fn determine_winner(player: Choice, opponent: Choice) -> Outcome {
  if player == opponent { return Outcome.Draw; };
  if player == Choice.Rock && opponent == Choice.Scissors { return Outcome.Win; };
  if player == Choice.Paper && opponent == Choice.Rock { return Outcome.Win; };
  if player == Choice.Scissors && opponent == Choice.Paper { return Outcome.Win; };
  Outcome.Lose
}

fn main() -> Int {
  let r1 = determine_winner(Choice.Rock, Choice.Scissors);
  let r2 = determine_winner(Choice.Paper, Choice.Scissors);
  let r3 = determine_winner(Choice.Rock, Choice.Rock);
  io.println((r1 == Outcome.Win).to_str());
  io.println((r2 == Outcome.Lose).to_str());
  io.println((r3 == Outcome.Draw).to_str());
  return 0;
}
